        this.outcomes.set(fact.id,{componentId:owner.key,disposition:'adapt',rule:'Use the frozen IDs and order from the actual existing target WooCommerce catalog. This is an explicitly labeled technical demo; source pet product names, images, prices and offers are not copied onto the target catalog.',verification:{kind:'presence',selector:`.${native44ModuleClass(owner.key)}`,property:'query',expected:{widgetType:'widgetType'in owner?owner.widgetType:'',productIds:owner.kind==='native-products'?owner.query?.ids??owner.tabs?.flatMap(tab=>tab.query.ids):[]}}});
